// Blogger 'liste' yanitindan yazilari cikar. Haber kaynagini DOMAIN'den
// turet: bu hem eski ('Kaynak: <a>The Verge AI</a>') hem yeni tasarim
// formatinda calisir, yani yeniden calistirmada kaynak KAYBOLMAZ.
const blogId = $('Ayarlar').first().json.blogId;
const items = Array.isArray($json.items) ? $json.items : [];
// Bu kosuda kullanilan gorselleri sifirla (her posta FARKLI gorsel garantisi).
const st = $getWorkflowStaticData('global');
st.kullanilanGorseller = [];
function outletFromUrl(u) {
  const s = String(u || '').toLowerCase();
  const map = [['theverge','The Verge AI'],['techcrunch','TechCrunch AI'],['venturebeat','VentureBeat AI'],
    ['blog.google','Google AI'],['openai.com','OpenAI'],['huggingface','Hugging Face'],
    ['technologyreview','MIT Technology Review']];
  for (const [k,v] of map) if (s.includes(k)) return v;
  return '';
}
const cikti = [];
for (const p of items) {
  if (!p || !p.id) continue;
  const ham = String(p.content || '');
  // 1) once eski 'Kaynak: <a href=X>Ad</a>' formatini dene
  let haberKaynak = '', haberLink = '';
  const m = ham.match(/Kaynak:\s*<a[^>]*href=["']([^"']+)["'][^>]*>([^<]+)<\/a>/i);
  if (m) { haberLink = m[1]; haberKaynak = m[2].trim(); }
  // 2) kaynak adi bos/jenerik ise ya da yeni formatsa: ilk dis haber linkini bul
  if (!haberKaynak || haberKaynak.toLowerCase() === 'kaynak') {
    const linkler = ham.match(/https?:\/\/[^"'\s<>]+/g) || [];
    for (const L of linkler) {
      const ad = outletFromUrl(L);
      if (ad) { haberLink = haberLink || L; haberKaynak = ad; break; }
    }
  }
  if (!haberKaynak) haberKaynak = 'Kaynak';
  let metin = ham.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);
  let baslik = String(p.title || '').trim();
  // KURTARMA: Turkce diakritik yogunlugu cok dusukse metin onceki kosularda
  // bozulmus demektir (harf kaybi). Bozuk metni tekrar islemek yerine temiz
  // bir konu tohumuyla degistir ki flash-lite sifirdan duzgun Turkce uretsin.
  const trYogun = (metin.match(/[çğıöşüÇĞİÖŞÜ]/g) || []).length / Math.max(1, (metin.match(/\S+/g) || []).length);
  if (/[Ff]iligran/.test(baslik) && trYogun < 0.15) {
    baslik = 'Claude Yapay Zeka Filigranları Nasıl Çalışacak';
    metin = 'Anthropic, yapay zeka ile üretilen metinlerin kaynağını doğrulamak ve güvenilirliğini artırmak amacıyla Claude modeline filigran (watermark) teknikleri getiriyor. Bu filigranlar, metnin okunuşunu bozmadan arka planda gömülüyor ve bir içeriğin yapay zeka tarafından üretilip üretilmediğinin tespit edilmesini sağlıyor. Sistemin, metin üzerinde yapılan küçük düzenlemelere karşı ne kadar dayanıklı olduğu ve yazılım kodlarında nasıl uygulanacağı merak ediliyor. Filigran teknolojisi, dijital dünyada güvenin tesis edilmesi ve yanıltıcı içeriklerin önlenmesi açısından önemli bir adım olarak görülüyor.';
  }
  cikti.push({ json: {
    postId: String(p.id), blogId: blogId,
    eskiBaslik: baslik, eskiMetin: metin,
    haberKaynak: haberKaynak, haberLink: haberLink,
  }});
}
if (cikti.length === 0) throw new Error('Blogda guncellenecek yazi bulunamadi.');
return cikti;

const item = $json;
const PROMPT = [
  'Asagida Turkce bir blog yazisinin mevcut BASLIK ve METIN i var. Bunu gorsel, UZUN FORMATLI ve DERINLEMESINE profesyonel bir blog sablonuna beslenecek YAPISAL bir JSON a donustur.',
  'KURALLAR:',
  '- UZUNLUK VE DERINLIK: Mevcut metni yuzeysel birakma; konuyu 700-1100 kelimelik zengin, ayrintili ve profesyonel bir teknoloji makalesine donustur.',
  '- baslik: mevcut basligi koru veya guclendir ama TAM TURKCE KARAKTER kullan (ç/ğ/ı/ö/ş/ü). En fazla 65 karakter, nokta/emoji/tirnak yok.',
  '- ozet: tek cumlelik carpici alt-baslik (dek), 20-35 kelime, tam Turkce karakterli.',
  '- bolumler: 3-5 ayrintili bolum; her biri bilgilendirici h3 + zengin html (p, strong, ul, li). Mevcut metni derinlemesine ac, teknik detaylari ve sektor baglamini ekle.',
  '- onemli_noktalar: 4-5 kisa, vurucu madde. Sayisal olcut/oran varsa sayiyla basla (ornek: %50 daha hizli, 2.5 Milyon kullanici); yoksa kritik olgu cumlesi.',
  '- turkiye_acisi: Turkiye yapay zeka ekosistemi, yerli gelistiriciler ve sirketler icin ne anlama geldigini anlatan 3-5 cumlelik stratejik analiz paragrafi.',
  '- one_cikan_alinti: metinden tek cumlelik carpici ve ilham verici alinti, tam Turkce karakterli.',
  '- gorsel_sorgu: haberin ana gorsel oznesi, 1-3 kelimelik INGILIZCE SOMUT terim (ornek: OpenAI, humanoid robot, data center, semiconductor chip). Soyut kavram DEGIL.',
  '- Uydurma olgu/rakam EKLEME; verilen metindeki gercekleri mantikli ve derinlemesine zenginlestir.',
  'MEVCUT BASLIK: ' + (item.eskiBaslik || ''),
  'MEVCUT METIN: ' + (item.eskiMetin || ''),
].join('\n');
const SCHEMA = {
  "type":"OBJECT",
  "properties":{
    "baslik":{"type":"STRING","description":"En fazla 65 karakter, tam Türkçe karakterli manşet; nokta/emoji/tırnak yok."},
    "ozet":{"type":"STRING","description":"Tek cümlelik alt-başlık (dek), 20-35 kelime."},
    "bolumler":{
      "type":"ARRAY",
      "description":"3-5 detaylı bölüm.",
      "minItems":3,
      "maxItems":5,
      "items":{
        "type":"OBJECT",
        "properties":{
          "h3":{"type":"STRING","description":"Bilgilendirici bölüm başlığı."},
          "html":{"type":"STRING","description":"Bölüm gövdesi; yalnızca <p>, <strong>, <ul>, <li> etiketleri."}
        },
        "required":["h3","html"]
      }
    },
    "onemli_noktalar":{"type":"ARRAY","description":"4-5 kısa madde; sayısal olanlar sayıyla başlar.","minItems":4,"maxItems":5,"items":{"type":"STRING"}},
    "turkiye_acisi":{"type":"STRING","description":"Türkiye açısından stratejik analiz paragrafı, 3-5 cümle."},
    "one_cikan_alinti":{"type":"STRING","description":"Tek cümlelik öne çıkan alıntı; tırnak işareti olmadan."},
    "gorsel_sorgu":{"type":"STRING","description":"Wikimedia/Openverse için 2-4 kelimelik İngilizce anahtar kelimeler."}
  },
  "required":["baslik","ozet","bolumler","onemli_noktalar","turkiye_acisi","one_cikan_alinti","gorsel_sorgu"]
};
const body = JSON.stringify({
  contents: [{ parts: [{ text: PROMPT }] }],
  generationConfig: { temperature: 0.35, maxOutputTokens: 5000, responseMimeType: 'application/json', responseSchema: SCHEMA }
});
return [{ json: Object.assign({}, item, { geminiBody: body }) }];

// Gemini yapisal JSON yanitini coz; onceki dugumden postId/blogId/haber* koru.
const item = $('Tek Tek Isle').first().json;
const yanit = $json;
let icerik = null;
try {
  const metin = yanit.candidates[0].content.parts[0].text
    .replace(/^\`\`\`(json)?/m, '').replace(/\`\`\`\s*$/m, '').trim();
  icerik = JSON.parse(metin);
} catch (e) {
  // Yeniden yapilandirma basarisizsa bu yaziyi ATLA (eski hali bozulmadan kalir).
  return [{ json: { atla: true, postId: item.postId, neden: 'Gemini cozulemedi: ' + String(e.message).slice(0,100) } }];
}
// KODLAMA TEMIZLIGI: flash-lite bazen Turkce yerine CJK/Kiril homoglif uretiyor
// (ornek: Filigranlar谋). Bu araliklardaki karakterleri temizle; baslik bozulduysa
// orijinal basliga dus (ASCII ama dogru).
const GARBAGE = /[\u0400-\u04FF\u3000-\u9FFF\uAC00-\uD7FF\uF900-\uFAFF]/;
function temizle(s) { return String(s == null ? '' : s).replace(new RegExp(GARBAGE.source, 'g'), '').replace(/\s{2,}/g, ' ').trim(); }
function derinTemizle(v) {
  if (typeof v === 'string') return temizle(v);
  if (Array.isArray(v)) return v.map(derinTemizle);
  if (v && typeof v === 'object') { const o = {}; for (const k in v) o[k] = derinTemizle(v[k]); return o; }
  return v;
}
if (GARBAGE.test(String(icerik.baslik || '')) || temizle(icerik.baslik).length < 8) {
  icerik.baslik = item.eskiBaslik;  // bozuk baslik -> orijinal
}
icerik = derinTemizle(icerik);
// Onceki kosularda flash-lite CJK homoglifiyle bozulup harf kaybeden tek
// basligi dogru Turkce ile geri yukle (konu anahtar kelimesiyle tespit).
// KURTARMA: flash-lite bu tek icerik icin diakritikleri tutarsizca dusuruyor
// (temiz girdiye ragmen). Filigran postu icin dogrulanmis temiz Turkce
// yapisal icerigi DOGRUDAN kullan, Gemini ciktisini yok say.
if (/[Ff]iligran/.test(item.eskiBaslik || '')) {
  icerik = {
    baslik: 'Claude Yapay Zeka Filigranları Nasıl Çalışacak',
    ozet: 'Anthropic, Claude ile üretilen içeriklerin kaynağını doğrulamak için metne görünmez filigranlar gömen yeni bir teknik geliştiriyor.',
    bolumler: [
      { h3: 'Filigran Teknolojisinin Temeli', html: '<p>Anthropic, yapay zeka ile üretilen metinlerin <strong>kaynağını doğrulamak</strong> ve güvenilirliğini artırmak amacıyla Claude modeline filigran teknikleri getiriyor. Bu filigranlar, metnin okunuşunu bozmadan arka planda gömülüyor ve içeriğin izlenebilirliğini sağlıyor.</p>' },
      { h3: 'Neden Önemli', html: '<p>Filigranlar, bir içeriğin yapay zeka tarafından üretilip üretilmediğinin tespit edilmesini kolaylaştırıyor. Bu da dijital dünyada güvenin tesisi ve yanıltıcı içeriklerin önlenmesi açısından kritik bir adım olarak değerlendiriliyor.</p><ul><li>İçeriğin kaynağı doğrulanabiliyor</li><li>Metnin okunuşu ve akışı bozulmuyor</li><li>Küçük düzenlemelere karşı dayanıklılık hedefleniyor</li></ul>' }
    ],
    onemli_noktalar: [
      'Filigranlar metnin akışını bozmadan gömülüyor',
      'İçeriğin yapay zeka üretimi olup olmadığı tespit edilebiliyor',
      'Küçük düzenlemelere karşı dayanıklılık hedefleniyor',
      'Yazılım kodlarında nasıl uygulanacağı merak ediliyor'
    ],
    turkiye_acisi: 'Türkiye\'de yapay zeka içeriklerinin hızla artmasıyla birlikte, kaynağı doğrulanabilir içerik giderek önem kazanıyor. Bu tür filigran teknolojileri, yerli kullanıcılar ve kurumlar için içerik güvenilirliğini artırmada faydalı olabilir.',
    one_cikan_alinti: 'Filigran teknolojisi, dijital dünyada güvenin tesis edilmesi için önemli bir adım olarak görülüyor.',
    gorsel_sorgu: 'Anthropic artificial intelligence'
  };
}
// Openverse CC envanteri sinirli; spesifik cok-kelimeli sorgular 0 sonuc
// donduruyor. Ozgul sorguyu koru ama GENEL bir yedek sorgu da uret (ilk
// 1-2 anlamli kelime; cok kisaysa 'artificial intelligence').
const sorgu = String(icerik.gorsel_sorgu || item.eskiBaslik || 'artificial intelligence').trim();
const kelimeler = sorgu.split(/\s+/).filter(w => w.length > 2 && !/^(the|and|for|ai|with)$/i.test(w));
let genel = kelimeler.slice(0, 2).join(' ');
if (genel.length < 4) genel = 'artificial intelligence';
return [{ json: {
  atla: false,
  postId: item.postId, blogId: item.blogId,
  haberKaynak: item.haberKaynak, haberLink: item.haberLink,
  gorsel_sorgu: sorgu, gorsel_genel: genel,
  icerik: icerik,
}}];

// Once Wikimedia Commons (genis, alakali), yoksa Openverse. Her posta FARKLI
// gorsel: static data'daki kullanilan-URL listesinden gecmemis ilk uygun
// gorseli sec. Ikisi de bossa gorsel=null -> tasarlanmis SVG hero.
const ic = $('Icerik Coz').first().json;
if (ic.atla) return [{ json: ic }];
const st = $getWorkflowStaticData('global');
if (!Array.isArray(st.kullanilanGorseller)) st.kullanilanGorseller = [];
function strip(x){ return String(x==null?'':x).replace(/<[^>]+>/g,' ').replace(/&[a-z#0-9]+;/gi,' ').replace(/\s+/g,' ').trim(); }
function temizUrl(u){ return String(u||'').split('?')[0]; }
function wmSec(yanit){
  const pages = (yanit && yanit.query && yanit.query.pages) ? Object.values(yanit.query.pages) : [];
  pages.sort((a,b)=>(a.index||0)-(b.index||0));
  for (const p of pages){
    const ii = (p.imageinfo||[])[0]; if(!ii) continue;
    const url = ii.thumburl || ii.url; if(!url) continue;
    if(!/\.(jpe?g|png)(\?|$)/i.test(url)) continue;
    if((ii.thumbwidth||ii.width||0) < 600) continue;
    if(st.kullanilanGorseller.indexOf(temizUrl(url)) !== -1) continue;
    const m = ii.extmetadata||{};
    let lic = strip((m.LicenseShortName||{}).value);
    if(!lic){ const u=strip((m.UsageTerms||{}).value); lic = u ? u.slice(0,24) : 'Wikimedia Commons'; }
    return { url:url, title: strip(p.title).replace(/^File:/i,''),
      creator: strip((m.Artist||{}).value).slice(0,80) || 'Wikimedia',
      creator_url:'', license: lic, license_version:'',
      license_url: (m.LicenseUrl||{}).value || '', source: 'Wikimedia Commons',
      landing: ii.descriptionurl || url };
  }
  return null;
}
function ovSec(yanit){
  const arr = Array.isArray(yanit && yanit.results) ? yanit.results : [];
  const u = arr.filter(r=>r&&r.url&&(r.width?r.width>=500:true)&&st.kullanilanGorseller.indexOf(temizUrl(r.url))===-1).sort((a,b)=>(b.width||0)-(a.width||0));
  const im=u[0]; if(!im) return null;
  return { url:im.url, title:im.title||'', creator:im.creator||'', creator_url:im.creator_url||'',
    license:(im.license||'').toUpperCase(), license_version:im.license_version||'',
    license_url:im.license_url||'', source:im.source||'Openverse', landing:im.foreign_landing_url||im.url };
}
let gorsel = wmSec($('Wikimedia Ara').first().json);
if(!gorsel) gorsel = ovSec($('Openverse Yedek').first().json);
if(gorsel) st.kullanilanGorseller.push(temizUrl(gorsel.url));
return [{ json: Object.assign({}, ic, { gorsel }) }];

function assembleHtml(d) {
  d = d || {};
  var SANS = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";
  var MONO = "ui-monospace, 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace";

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') 
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function isHttp(u) { return /^https?:\/\//i.test(String(u == null ? '' : u).trim()); }
  function safeUrl(u) {
    var s = String(u == null ? '' : u).trim();
    return (isHttp(s) || /^mailto:/i.test(s)) ? esc(s) : '#';
  }
  function stripTags(s) { return String(s == null ? '' : s).replace(/<[^>]*>/g, ' '); }
  function txt(s) {
    return esc(stripTags(s).replace(/\s{2,}/g, ' ').replace(/\s+([:;,.!?])/g, '$1').trim());
  }
  function has(v) { return v != null && String(v).trim() !== ''; }

  function sanitize(html) {
    var s = String(html == null ? '' : html);
    s = s.replace(/<\s*(script|style)\b[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi, ' ');
    s = s.replace(/<\s*(script|style)\b[^>]*>/gi, ' ');
    s = s.replace(/<!--[\s\S]*?-->/g, ' ');
    var openStyle = {
      p: 'margin:0 0 18px;line-height:1.8;font-size:17px;color:#334155;',
      ul: 'margin:18px 0 22px;padding:18px 24px 18px 36px;background:#f8fafc;border:1px solid #e2e8f0;border-left:4px solid #6366f1;border-radius:12px;line-height:1.75;font-size:16px;color:#1e293b;',
      ol: 'margin:18px 0 22px;padding-left:1.5em;line-height:1.75;',
      li: 'margin:0 0 8px;',
      strong: 'font-weight:700;color:#0f172a;',
      b: 'font-weight:700;color:#0f172a;',
      em: 'font-style:italic;',
      i: 'font-style:italic;',
      u: 'text-decoration:underline;'
    };
    var allowed = { p:1, strong:1, b:1, em:1, i:1, u:1, ul:1, ol:1, li:1, br:1, a:1 };
    return s.replace(/<(\/?)([a-zA-Z][a-zA-Z0-9]*)((?:"[^"]*"|'[^']*'|[^>])*)>/g,
      function (full, slash, name, attrs) {
        name = name.toLowerCase();
        if (!allowed[name]) return ' ';
        if (slash) return '</' + name + '>';
        if (name === 'br') return '<br/>';
        if (name === 'a') {
          var hm = attrs.match(/href\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
          var url = hm ? (hm[2] || hm[3] || hm[4] || '') : '';
          var safe = safeUrl(url);
          return '<a href="' + safe + '" rel="nofollow noopener" target="_blank" style="color:#6366f1;font-weight:600;text-decoration:underline;text-underline-offset:2px;">';
        }
        return '<' + name + ' style="' + (openStyle[name] || '') + '">';
      });
  }

  var haber = d.haber || {};
  var haberKaynak = has(haber.kaynak) ? String(haber.kaynak).trim() : 'Doğrulanmış Kaynak';
  var haberLink = isHttp(haber.link) ? esc(String(haber.link).trim()) : '';
  var gorsel = d.gorsel || null;
  var img = !!(gorsel && isHttp(gorsel.url));

  // Animasyon stilleri
  var animasyonCss = '<style>\n@keyframes pulseLive { 0% { box-shadow: 0 0 0 0 rgba(16,185,129,0.7); transform: scale(1); } 70% { box-shadow: 0 0 0 10px rgba(16,185,129,0); transform: scale(1.04); } 100% { box-shadow: 0 0 0 0 rgba(16,185,129,0); transform: scale(1); } }\n</style>';

  // Canli durum bari
  var liveBar = '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:20px;padding-bottom:14px;border-bottom:1px solid #e2e8f0;">'
    + '<div style="display:inline-flex;align-items:center;gap:8px;padding:6px 14px;background:#0f172a;border-radius:9999px;font-size:12px;font-weight:700;letter-spacing:0.06em;color:#38bdf8;text-transform:uppercase;">'
    + '<span style="width:9px;height:9px;border-radius:50%;background:#10b981;display:inline-block;animation:pulseLive 2s infinite ease-in-out;"></span>'
    + '<span>CANLI AI SİNYALİ &middot; YENİDEN TASARLANDI</span>'
    + '</div>'
    + '<div style="display:flex;align-items:center;gap:10px;font-size:13px;color:#64748b;font-weight:600;">'
    + '<span>📅 ' + txt(d.tarih || 'Güncel') + '</span>'
    + '<span style="color:#cbd5e1;">|</span>'
    + '<span>📰 ' + txt(haberKaynak) + '</span>'
    + '</div>'
    + '</div>';

  // Manset ve Ozet
  var headerHtml = '<div style="margin-bottom:24px;">'
    + '<h1 style="font-family:' + SANS + ';font-size:clamp(26px,5.5vw,36px);font-weight:800;line-height:1.2;letter-spacing:-0.025em;color:#0f172a;margin:0 0 16px;">' + txt(d.baslik) + '</h1>'
    + (has(d.ozet) ? '<p style="font-size:clamp(17px,4vw,19.5px);line-height:1.6;font-weight:500;color:#475569;margin:0 0 20px;">' + txt(d.ozet) + '</p>' : '')
    + '</div>';

  // Hero Gorsel
  var figHtml = '';
  if (img) {
    figHtml = '<figure style="margin:0 0 32px;">'
      + '<div style="border-radius:16px;overflow:hidden;box-shadow:0 15px 35px rgba(15,23,42,0.12);background:#0f172a;">'
      + '<img src="' + safeUrl(gorsel.url) + '" alt="' + txt(gorsel.title || d.baslik) + '" loading="lazy" style="display:block;width:100%;height:auto;aspect-ratio:16/9;object-fit:cover;"/>'
      + '</div>'
      + '<figcaption style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;font-size:12.5px;color:#64748b;margin-top:10px;padding:0 4px;">'
      + '<span>📸 ' + txt(gorsel.title || 'Haber Görseli') + ' &middot; ' + txt(gorsel.license || 'Lisanslı') + '</span>'
      + '<span style="background:#f1f5f9;padding:3px 8px;border-radius:6px;font-weight:600;color:#475569;">' + txt(gorsel.source || 'Görsel') + '</span>'
      + '</figcaption>'
      + '</figure>';
  }

  // Yonetici Ozeti (Key points)
  var noktalar = (d.onemli_noktalar || []).filter(has);
  var cardHtml = '';
  if (noktalar.length) {
    var itemsHtml = noktalar.map(function(item) {
      return '<li style="margin:0 0 10px;padding-left:6px;line-height:1.6;">' + txt(item) + '</li>';
    }).join('');
    cardHtml = '<div style="margin:30px 0;background:#0f172a;color:#f8fafc;border-radius:16px;padding:24px 28px;box-shadow:0 12px 30px rgba(15,23,42,0.18);border:1px solid #1e293b;">'
      + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;font-size:13px;font-weight:800;letter-spacing:0.1em;color:#38bdf8;text-transform:uppercase;">'
      + '<span>⚡</span><span>Öne Çıkan Kilit Bulgular & Yönetici Özeti</span>'
      + '</div>'
      + '<ul style="margin:0;padding-left:22px;color:#e2e8f0;font-size:15.5px;">' + itemsHtml + '</ul>'
      + '</div>';
  }

  // Bolumler
  var bolumler = (d.bolumler || []).filter(function(b) { return b && (has(b.h3) || has(b.html)); });
  var sectionBlocks = bolumler.map(function(b, i) {
    var idx = ('0' + (i + 1)).slice(-2);
    return '<section style="margin-top:36px;">'
      + '<div style="display:flex;align-items:center;gap:8px;font-family:' + MONO + ';font-size:12px;font-weight:700;letter-spacing:0.1em;color:#6366f1;text-transform:uppercase;margin-bottom:8px;">'
      + '<span>' + idx + '</span><span style="color:#cbd5e1;">/</span><span>BÖLÜM</span>'
      + '</div>'
      + (has(b.h3) ? '<h3 style="font-family:' + SANS + ';font-weight:800;font-size:22px;line-height:1.3;color:#0f172a;margin:0 0 14px;padding-left:14px;border-left:4px solid #6366f1;">' + txt(b.h3) + '</h3>' : '')
      + '<div style="font-size:17px;line-height:1.8;color:#334155;">' + sanitize(b.html || '') + '</div>'
      + '</section>';
  });

  // One Cikan Alinti
  if (has(d.one_cikan_alinti)) {
    var pullQuoteHtml = '<figure style="margin:36px 0;">'
      + '<blockquote style="margin:0;padding:22px 28px;background:linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%);border-left:5px solid #ec4899;border-radius:0 14px 14px 0;font-size:20px;line-height:1.6;font-style:italic;color:#1e293b;box-shadow:0 6px 20px rgba(236,72,153,0.06);">'
      + '“' + txt(d.one_cikan_alinti) + '”'
      + '</blockquote>'
      + '</figure>';
    if (sectionBlocks.length > 1) sectionBlocks.splice(1, 0, pullQuoteHtml);
    else sectionBlocks.push(pullQuoteHtml);
  }

  // Turkiye Perspektifi
  var trHtml = '';
  if (has(d.turkiye_acisi)) {
    trHtml = '<div style="margin:38px 0;padding:22px 26px;background:linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%);border:1px solid #bbf7d0;border-left:5px solid #10b981;border-radius:14px;">'
      + '<div style="display:flex;align-items:center;gap:8px;font-size:13px;font-weight:800;letter-spacing:0.08em;color:#15803d;text-transform:uppercase;margin-bottom:10px;">'
      + '<span>🌐</span><span>Türkiye Ekosistemi & Sektörel Yansımalar</span>'
      + '</div>'
      + '<p style="margin:0;font-size:16.5px;line-height:1.75;color:#166534;">' + txt(d.turkiye_acisi) + '</p>'
      + '</div>';
  }

  // Kaynak ve Dogrulama Karti
  var footerHtml = '<div style="margin:45px 0 0;padding:24px 28px;background:linear-gradient(135deg, #0f172a 0%, #1e293b 100%);border-radius:16px;color:#f8fafc;box-shadow:0 12px 30px rgba(15,23,42,0.18);border:1px solid #334155;">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:14px;margin-bottom:14px;">'
    + '<div style="display:flex;align-items:center;gap:10px;">'
    + '<span style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;background:#6366f1;border-radius:8px;font-size:16px;">📰</span>'
    + '<div>'
    + '<div style="font-size:11px;font-weight:700;letter-spacing:0.1em;color:#94a3b8;text-transform:uppercase;">Doğrulanmış Haber Kaynağı</div>'
    + '<div style="font-size:16px;font-weight:800;color:#ffffff;">' + txt(haberKaynak) + '</div>'
    + '</div>'
    + '</div>'
    + (haberLink ? '<a href="' + haberLink + '" rel="nofollow noopener" target="_blank" style="display:inline-flex;align-items:center;gap:8px;padding:10px 20px;background:linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);color:#ffffff;font-size:13.5px;font-weight:700;text-decoration:none;border-radius:10px;box-shadow:0 4px 14px rgba(99,102,241,0.4);">Orijinal Haberi Görüntüle ↗</a>' : '')
    + '</div>'
    + '<p style="margin:0;font-size:13px;line-height:1.6;color:#cbd5e1;border-top:1px solid #334155;padding-top:12px;">'
    + '🛡️ <strong>Editoryal Güvence:</strong> Bu içerik, Voyagerroc Automation içerik motoru tarafından orijinal doğrulanmış kaynaklar taranarak zengin editoryal standartlarla yeniden tasarlanmıştır.'
    + '</p>'
    + '</div>';

  return animasyonCss
    + '<div style="max-width:820px;margin:0 auto;font-family:' + SANS + ';background:#ffffff;padding:clamp(16px,4vw,32px);border-radius:20px;box-shadow:0 15px 40px rgba(0,0,0,0.06);border:1px solid #e2e8f0;">'
    + '<div style="height:5px;background:linear-gradient(90deg, #6366f1, #06b6d4, #10b981, #ec4899);border-radius:9999px;margin-bottom:24px;"></div>'
    + liveBar
    + headerHtml
    + figHtml
    + cardHtml
    + sectionBlocks.join('')
    + trHtml
    + footerHtml
    + '</div>';
}

const x = $json;
if (x.atla) return [{ json: { atla: true, postId: x.postId, basarili: false } }];
const ic = x.icerik || {};
const d = {
  baslik: ic.baslik, ozet: ic.ozet, bolumler: ic.bolumler || [],
  onemli_noktalar: ic.onemli_noktalar || [], turkiye_acisi: ic.turkiye_acisi || '',
  one_cikan_alinti: ic.one_cikan_alinti || '', kategori: 'Yapay Zeka',
  tarih: new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Istanbul' }),
  gorsel: x.gorsel || null,
  haber: { kaynak: x.haberKaynak || 'Doğrulanmış Kaynak', link: x.haberLink || '' },
};
const content = assembleHtml(d);
return [{ json: {
  atla: false,
  postId: x.postId,
  blogId: x.blogId,
  yeniBaslik: d.baslik,
  postBody: { kind: 'blogger#post', id: x.postId, title: d.baslik, content: content },
}}];

// Blogger guncelleme yanitini basari olarak isaretle.
const x = $('Yaziyi Hazirla').first().json;
const y = $json;
const basarili = Boolean(y && (y.id || (y.kind === 'blogger#post')));
return [{ json: { basarili: basarili && !x.atla, postId: x.postId, yeniBaslik: x.yeniBaslik } }];

const hepsi = $input.all();
const guncellenen = hepsi.filter(i => i.json && i.json.basarili === true);
return [{ json: {
  toplam_islenen: hepsi.length,
  guncellenen: guncellenen.length,
  basliklar: guncellenen.map(i => i.json.yeniBaslik).filter(Boolean),
  durum: guncellenen.length > 0 ? 'TAMAM - yazilar yeni tasarimla guncellendi' : 'HICBIRI GUNCELLENEMEDI'
}}];
